<body>
<div class="wrap">
  <h1>Szokáskövető</h1>
  <p class="hint">Jelöld be azokat a napokat, amikor teljesítetted a szokást. A sorozat számolja, hány egymást követő nap ment egyben.</p>
  <div class="summary">
    <span class="big" id="totalStreak">0</span>
    <span class="lbl">napos leghosszabb sorozat</span>
  </div>
  <div id="list"></div>
  <form class="add" id="addForm">
    <label for="habitInput" class="sr-only">Új szokás neve</label>
    <input id="habitInput" type="text" maxlength="40" placeholder="pl. 10 perc séta" autocomplete="off">
    <button type="submit" id="addBtn">Hozzáad</button>
  </form>
  <p class="sr-only" role="status" aria-live="polite" id="status"></p>
</div>
<script>
  const DOW = ['H','K','Sze','Cs','P','Szo','V'];
  const KEY = 'habit-tracker';
  const listEl = document.getElementById('list');
  const totalEl = document.getElementById('totalStreak');
  const statusEl = document.getElementById('status');
  const form = document.getElementById('addForm');
  const input = document.getElementById('habitInput');
  const addBtn = document.getElementById('addBtn');

  const store = (window.alfy && window.alfy.storage) ? window.alfy.storage : null;
  let habits = [];

  function mondayOf(d) {
    const day = (d.getDay() + 6) % 7;
    const m = new Date(d);
    m.setDate(d.getDate() - day);
    m.setHours(0,0,0,0);
    return m;
  }
  function dateStr(d) {
    return d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0') + '-' + String(d.getDate()).padStart(2,'0');
  }
  function buildWeek() {
    const now = new Date();
    const mon = mondayOf(now);
    const today = new Date(); today.setHours(0,0,0,0);
    return Array.from({length:7}, (_, i) => {
      const d = new Date(mon); d.setDate(mon.getDate() + i);
      return { key: dateStr(d), dow: DOW[i], today: d.getTime() === today.getTime() };
    });
  }
  function currentStreak(habit) {
    const done = habit.done || {};
    const today = new Date(); today.setHours(0,0,0,0);
    let streak = 0, i = 0;
    while (done[dateStr(new Date(today.getTime() - i * 86400000))]) { streak++; i++; }
    return streak;
  }
  function save() {
    if (store) store.set(KEY, habits).catch(() => {});
  }
  function announce(msg) { statusEl.textContent = msg; }

  function render() {
    listEl.innerHTML = '';
    if (!habits.length) {
      const e = document.createElement('div');
      e.className = 'empty';
      e.textContent = 'Még nincs szokás. Írd be fent a nevét, és nyomj a Hozzáad gombra.';
      listEl.appendChild(e);
    } else {
      const week = buildWeek();
      const ul = document.createElement('ul');
      ul.className = 'habits';
      let maxStreak = 0;
      habits.forEach((habit, idx) => {
        const streak = currentStreak(habit);
        maxStreak = Math.max(maxStreak, streak);
        const li = document.createElement('li');
        li.className = 'habit';

        const top = document.createElement('div');
        top.className = 'habit-top';
        const h2 = document.createElement('h2');
        h2.textContent = habit.name;
        const badge = document.createElement('span');
        badge.className = 'streak' + (streak > 0 ? ' on' : '');
        badge.textContent = streak > 0 ? '🔥 ' + streak + ' nap' : 'nincs sorozat';
        top.appendChild(h2); top.appendChild(badge);

        const days = document.createElement('div');
        days.className = 'days';
        week.forEach(day => {
          const cell = document.createElement('div');
          cell.className = 'cell' + (day.today ? ' today' : '');
          const dow = document.createElement('span');
          dow.className = 'dow'; dow.textContent = day.dow;
          const btn = document.createElement('button');
          btn.type = 'button'; btn.className = 'check' + (day.today ? ' today' : '');
          const checked = !!habit.done[day.key];
          btn.setAttribute('aria-pressed', String(checked));
          btn.textContent = checked ? '✓' : '·';
          btn.setAttribute('aria-label', habit.name + ' – ' + day.dow);
          btn.addEventListener('click', () => {
            habit.done[day.key] = !checked;
            save(); render();
            announce(habit.name + (habit.done[day.key] ? ' bejelölve' : ' jelölés törölve'));
          });
          cell.appendChild(dow); cell.appendChild(btn);
          days.appendChild(cell);
        });

        const del = document.createElement('button');
        del.type = 'button'; del.className = 'del';
        del.textContent = 'Szokás törlése';
        del.setAttribute('aria-label', habit.name + ' törlése');
        del.addEventListener('click', () => {
          const name = habit.name;
          habits.splice(idx, 1);
          save(); render();
          announce(name + ' törölve');
        });

        li.appendChild(top); li.appendChild(days); li.appendChild(del);
        ul.appendChild(li);
      });
      listEl.appendChild(ul);
      totalEl.textContent = maxStreak;
    }
    addBtn.disabled = !input.value.trim();
  }

  form.addEventListener('submit', e => {
    e.preventDefault();
    const name = input.value.trim();
    if (!name) return;
    habits.push({ name, done: {} });
    input.value = '';
    save(); render();
    announce(name + ' hozzáadva');
    input.focus();
  });
  input.addEventListener('input', () => { addBtn.disabled = !input.value.trim(); });

  async function init() {
    if (store) {
      try {
        const saved = await store.get(KEY);
        if (Array.isArray(saved)) habits = saved;
      } catch (e) { habits = []; }
    }
    render();
  }
  init();
</script>
</body>
